// ═══════════════════════════════════════════════════════════
// ─── UNIQUE IDS ───────────────────────────────────────────
// Assigns a unique sequential id to every product so the
// quick-view modal always opens the correct item.
// ═══════════════════════════════════════════════════════════

PRODUCTS.forEach((p, i) => { p.id = i + 1; });

// Small version of an image for grids/cards (full size is used in modals/lightbox)
function thumbOf(src) {
  return (src && src.indexOf('images/') === 0) ? 'images/thumbs/' + src.slice(7) : src;
}
